import unittest
from datetime import date

from huskyutils.dates import add_business_days


class TestIssue4(unittest.TestCase):
    def test_issue_example_thursday_plus_3_is_tuesday(self):
        self.assertEqual(add_business_days(date(2026, 11, 5), 3), date(2026, 11, 10))

    def test_docstring_friday_plus_1_is_monday(self):
        self.assertEqual(add_business_days(date(2026, 11, 6), 1), date(2026, 11, 9))

    def test_docstring_friday_plus_1_with_monday_holiday(self):
        self.assertEqual(
            add_business_days(date(2026, 11, 6), 1, holidays={date(2026, 11, 9)}),
            date(2026, 11, 10),
        )

    def test_days_zero_returns_start_even_on_weekend(self):
        self.assertEqual(add_business_days(date(2026, 11, 7), 0), date(2026, 11, 7))

    def test_saturday_plus_1_is_monday(self):
        self.assertEqual(add_business_days(date(2026, 11, 7), 1), date(2026, 11, 9))

    def test_result_is_always_business_day(self):
        start = date(2026, 11, 1)
        for n in range(1, 30):
            r = add_business_days(start, n)
            self.assertLess(r.weekday(), 5, f"n={n} gave {r}")
            self.assertGreater(r, start)

    def test_full_week_is_five_business_days(self):
        # Monday + 5 business days = next Monday
        self.assertEqual(add_business_days(date(2026, 11, 2), 5), date(2026, 11, 9))


