import copy
import unittest

from huskyutils.intervals import merge_intervals


class TestIssue5(unittest.TestCase):
    def test_issue_example_unsorted(self):
        self.assertEqual(merge_intervals([[8, 10], [1, 3], [2, 6]]), [[1, 6], [8, 10]])

    def test_docstring_example_1(self):
        self.assertEqual(merge_intervals([[1, 3], [2, 6], [8, 10]]), [[1, 6], [8, 10]])

    def test_docstring_example_2_touching(self):
        self.assertEqual(merge_intervals([[1, 4], [4, 5]]), [[1, 5]])

    def test_result_sorted_by_start_any_input_order(self):
        self.assertEqual(
            merge_intervals([[20, 25], [5, 6], [10, 12], [1, 2]]),
            [[1, 2], [5, 6], [10, 12], [20, 25]],
        )

    def test_unsorted_with_containment(self):
        self.assertEqual(merge_intervals([[5, 9], [1, 10], [3, 4]]), [[1, 10]])

    def test_unsorted_touching_chain(self):
        self.assertEqual(merge_intervals([[6, 7], [4, 6], [1, 4]]), [[1, 7]])

    def test_input_not_modified(self):
        data = [[8, 10], [1, 3], [2, 6]]
        original = copy.deepcopy(data)
        merge_intervals(data)
        self.assertEqual(data, original)

    def test_returns_new_list(self):
        data = [[1, 2], [3, 4]]
        result = merge_intervals(data)
        result[0][1] = 99
        self.assertEqual(data, [[1, 2], [3, 4]])


