import unittest

from huskyutils.shipping import shipping_cost


class TestIssue6(unittest.TestCase):
    def test_exactly_1kg_is_5_dollars(self):
        # Issue #6: a 1 kg package must ship for $5.00 (500 cents), not $9.00.
        self.assertEqual(shipping_cost(1), 500)

    def test_docstring_examples(self):
        self.assertEqual(shipping_cost(0.4), 500)
        self.assertEqual(shipping_cost(5.2), 1100)

    def test_up_to_1kg_inclusive(self):
        self.assertEqual(shipping_cost(0.5), 500)
        self.assertEqual(shipping_cost(1.0), 500)

    def test_over_1kg_up_to_5kg_is_9_dollars(self):
        self.assertEqual(shipping_cost(1.0001), 900)
        self.assertEqual(shipping_cost(1.5), 900)
        self.assertEqual(shipping_cost(5), 900)

    def test_over_5kg(self):
        self.assertEqual(shipping_cost(5.5), 1100)
        self.assertEqual(shipping_cost(6), 1100)
        self.assertEqual(shipping_cost(6.5), 1300)


