import unittest

from huskyutils.cards import truncate


class TestIssue10(unittest.TestCase):
    def test_issue_example_fits_in_30(self):
        s = truncate("Wireless noise-cancelling headphones with case", 30)
        self.assertLessEqual(len(s), 30)

    def test_issue_example_exact_output(self):
        self.assertEqual(
            truncate("Wireless noise-cancelling headphones with case", 30),
            "Wireless noise-cancelling...",
        )

    def test_docstring_short_unchanged(self):
        self.assertEqual(truncate("Wireless headphones", 30), "Wireless headphones")

    def test_at_most_limit_unchanged(self):
        self.assertEqual(truncate("USB-C dock", 10), "USB-C dock")

    def test_first_word_too_long_hard_cut(self):
        # limit 10 -> budget 7 -> first 7 chars + "..."
        self.assertEqual(truncate("Wireless headphones", 10), "Wireles...")

    def test_result_never_exceeds_limit(self):
        text = "Mechanical keyboard with brown switches and a detachable cable"
        for limit in range(10, len(text)):
            s = truncate(text, limit)
            self.assertLessEqual(len(s), limit, (limit, s))
            self.assertTrue(s.endswith("..."), (limit, s))

    def test_words_not_cut_and_no_space_before_ellipsis(self):
        text = "Mechanical keyboard with brown switches and a detachable cable"
        s = truncate(text, 30)
        self.assertFalse(s.endswith(" ..."))
        body = s[:-3]
        self.assertTrue(text.startswith(body))
        self.assertTrue(text[len(body):].startswith(" "))


if __name__ == "__main__":
    unittest.main()
